-- 046_chain_dish_english_names.sql
-- #126: English names for chain dishes that only had a Korean name.
-- Generated by scripts/chain_menus/build_046.py from supabase/data/chains/*.json; do not edit by hand.
-- The names were translated by the Mukji team; they are not the brands' official English.
-- Changes only names that are still a copy of the Korean name, so it never overwrites a
-- name fixed by hand, and it is safe to re-run.

begin;

create temp table _chain_names (chain_id text, dish_no int, name_ko text, name_en text) on commit drop;

-- 1. the source table (037)
update public.chain_menu_dishes cd
   set name_en = v.name_en
  from _chain_names v
 where cd.chain_id = v.chain_id and cd.dish_no = v.dish_no
   and cd.name_ko = v.name_ko
   and (cd.name_en = cd.name_ko or btrim(coalesce(cd.name_en, '')) = '');

-- 2. the dishes 037's apply_chain_menus() copied to each branch
update public.dishes d
   set name_en = v.name_en
  from _chain_names v
 where d.id like '%-chain-' || v.chain_id || '-' || v.dish_no
   and d.name_ko = v.name_ko
   and (d.name_en = d.name_ko or btrim(coalesce(d.name_en, '')) = '');

commit;

-- Check: no chain dish should still have its Korean name as the English name.
--   select chain_id, count(*) from public.chain_menu_dishes where name_en = name_ko group by 1;
--   select count(*) from public.dishes where id like '%-chain-%' and name_en = name_ko;
